INSERT INTO `ec_products` (`id`, `name`, `description`, `content`, `status`, `images`, `video_media`, `sku`, `order`, `quantity`, `allow_checkout_when_out_of_stock`, `with_storehouse_management`, `stock_status`, `is_featured`, `is_preorder_enabled`, `brand_id`, `is_variation`, `sale_type`, `price`, `sale_price`, `start_date`, `end_date`, `length`, `wide`, `height`, `weight`, `tax_id`, `views`, `created_at`, `updated_at`, `store_id`, `created_by_id`, `created_by_type`, `approved_by`, `image`, `product_type`, `barcode`, `cost_per_item`, `generate_license_code`, `notify_attachment_updated`, `specification_table_id`, `minimum_order_quantity`, `maximum_order_quantity`) VALUES
(1, 'Vintage Denim Jacket', '<p>Step out in style with these leather ankle boots, crafted with a sleek design and comfortable block heel. Versatile enough to pair with both dresses and jeans.</p>', '<div class=\"row justify-content-center\"><div class=\"col-xl-10\"><div class=\"tp-product-details-desc-item pb-105\"><div class=\"row\"><div class=\"col-lg-6\"><div class=\"pt-25\"><p><span>Women\'s Floral Dress</span></p><h3 class=\"tp-product-details-desc-title\">Elegance Redefined</h3><p>Embrace timeless elegance with our exquisite women\'s floral dress. Crafted from luxurious fabrics and adorned with delicate floral patterns, this dress exudes grace and sophistication. Whether attending a garden party or a formal event, you\'ll make a stunning impression in this captivating ensemble.</p></div><div><h3 class=\"tp-product-details-desc-title\">Flawless Fit and Comfort</h3><p>Designed for both style and comfort, our floral dress features a tailored silhouette that flatters every figure. The soft, breathable fabric ensures all-day comfort, while the fitted bodice and flowing skirt create a graceful silhouette. Feel confident and poised with every step you take.</p></div></div><div class=\"col-lg-6\"><div class=\"tp-product-details-desc-thumb\"><img src=\"/storage/fashion/products/product-1.png\" alt=\"Women\'s Floral Dress\"></div></div></div></div><div class=\"tp-product-details-desc-item pb-75\"><div class=\"row\"><div class=\"col-lg-7\"><div class=\"tp-product-details-desc-thumb\"><img src=\"/storage/fashion/products/product-2.png\" alt=\"Back View of Floral Dress\"></div></div><div class=\"col-lg-5 order-first order-lg-last\"><div class=\"des-content-2 pl-40\"><h3 class=\"tp-product-details-desc-title\">Versatile Style</h3><p>Transition effortlessly from day to night with our versatile floral dress. Pair it with sandals and a sunhat for a chic daytime look, or dress it up with heels and statement jewelry for an evening soirée. However you style it, you\'ll radiate confidence and charm.</p></div></div></div></div><div class=\"tp-product-details-desc-item\"><div class=\"row\"><div class=\"col-xl-12\"><div class=\"tp-product-details-desc-banner text-center m-img\"><h3 class=\"tp-product-details-desc-banner-title tp-product-details-desc-title\">Quality Craftsmanship</h3><p><img src=\"/storage/fashion/products/product-3.png\" alt=\"Fashion Atelier\"></p></div></div></div></div></div></div>', 'published', '[\"fashion\\/sliders\\/123997.jpg\"]', '[[{\"key\":\"file\",\"value\":\"main\\/video\\/video-1.mp4\"},{\"key\":\"url\",\"value\":null},{\"key\":\"thumbnail\",\"value\":null}]]', '61-110', 0, 9, 0, 1, 'on_backorder', 0, 1, 5, 0, 0, 25000, 20000, NULL, NULL, 14, 18, 14, 809, NULL, 100083, '2025-05-01 21:04:08', '2025-10-01 12:10:18', 7, 0, 'Botble\\ACL\\Models\\User', 0, 'fashion/sliders/123997.jpg', 'physical', NULL, NULL, 0, 0, 2, 0, 0),
(2, 'Floral Maxi Dress', '<p>Top off your look with this chic fedora hat, crafted with a classic silhouette and a timeless appeal. A must-have accessory for any fashion-forward wardrobe.</p>', '<div class=\"row justify-content-center\"><div class=\"col-xl-10\"><div class=\"tp-product-details-desc-item pb-105\"><div class=\"row\"><div class=\"col-lg-6\"><div class=\"pt-25\"><p><span>Women\'s Floral Dress</span></p><h3 class=\"tp-product-details-desc-title\">Elegance Redefined</h3><p>Embrace timeless elegance with our exquisite women\'s floral dress. Crafted from luxurious fabrics and adorned with delicate floral patterns, this dress exudes grace and sophistication. Whether attending a garden party or a formal event, you\'ll make a stunning impression in this captivating ensemble.</p></div><div><h3 class=\"tp-product-details-desc-title\">Flawless Fit and Comfort</h3><p>Designed for both style and comfort, our floral dress features a tailored silhouette that flatters every figure. The soft, breathable fabric ensures all-day comfort, while the fitted bodice and flowing skirt create a graceful silhouette. Feel confident and poised with every step you take.</p></div></div><div class=\"col-lg-6\"><div class=\"tp-product-details-desc-thumb\"><img src=\"/storage/fashion/products/product-1.png\" alt=\"Women\'s Floral Dress\"></div></div></div></div><div class=\"tp-product-details-desc-item pb-75\"><div class=\"row\"><div class=\"col-lg-7\"><div class=\"tp-product-details-desc-thumb\"><img src=\"/storage/fashion/products/product-2.png\" alt=\"Back View of Floral Dress\"></div></div><div class=\"col-lg-5 order-first order-lg-last\"><div class=\"des-content-2 pl-40\"><h3 class=\"tp-product-details-desc-title\">Versatile Style</h3><p>Transition effortlessly from day to night with our versatile floral dress. Pair it with sandals and a sunhat for a chic daytime look, or dress it up with heels and statement jewelry for an evening soirée. However you style it, you\'ll radiate confidence and charm.</p></div></div></div></div><div class=\"tp-product-details-desc-item\"><div class=\"row\"><div class=\"col-xl-12\"><div class=\"tp-product-details-desc-banner text-center m-img\"><h3 class=\"tp-product-details-desc-banner-title tp-product-details-desc-title\">Quality Craftsmanship</h3><p><img src=\"/storage/fashion/products/product-3.png\" alt=\"Fashion Atelier\"></p></div></div></div></div></div></div>', 'published', '[]', '[[{\"key\":\"file\",\"value\":\"main\\/video\\/video-2.mp4\"},{\"key\":\"url\",\"value\":null},{\"key\":\"thumbnail\",\"value\":\"main\\/video\\/2.jpg\"}]]', 'KA-185', 0, 16, 0, 1, 'on_backorder', 0, 1, 3, 0, 0, 2284, 2172, NULL, NULL, 16, 10, 11, 593, NULL, 117730, '2025-05-01 21:04:08', '2025-10-01 12:19:52', 3, 0, 'Botble\\ACL\\Models\\User', 0, NULL, 'physical', NULL, NULL, 0, 0, 2, 0, 0),
(3, 'Leather Ankle Boots', 'Top off your look with this chic fedora hat, crafted with a classic silhouette and a timeless appeal. A must-have accessory for any fashion-forward wardrobe.', '<div class=\"row justify-content-center\">\n    <div class=\"col-xl-10\">\n        <div class=\"tp-product-details-desc-item pb-105\">\n            <div class=\"row\">\n                <div class=\"col-lg-6\">\n                    <div class=\"pt-25\">\n                        <span>Women\'s Floral Dress</span>\n                        <h3 class=\"tp-product-details-desc-title\">Elegance Redefined</h3>\n                        <p>\n                            Embrace timeless elegance with our exquisite women\'s floral dress. Crafted from luxurious fabrics and adorned with delicate floral patterns, this dress exudes grace and sophistication. Whether attending a garden party or a formal event, you\'ll make a stunning impression in this captivating ensemble.\n                        </p>\n                    </div>\n                    <div>\n                        <h3 class=\"tp-product-details-desc-title\">Flawless Fit and Comfort</h3>\n                        <p>\n                            Designed for both style and comfort, our floral dress features a tailored silhouette that flatters every figure. The soft, breathable fabric ensures all-day comfort, while the fitted bodice and flowing skirt create a graceful silhouette. Feel confident and poised with every step you take.\n                        </p>\n                    </div>\n                </div>\n                <div class=\"col-lg-6\">\n                    <div class=\"tp-product-details-desc-thumb\">\n                        <img src=\"/storage/fashion/products/product-1.png\" alt=\"Women\'s Floral Dress\">\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class=\"tp-product-details-desc-item pb-75\">\n            <div class=\"row\">\n                <div class=\"c